// Lista principal: só o que NÃO existe na farmácia de jeito nenhum —
// zerado e sem estoque em outro cadastro do mesmo nome, em outra marca
// equivalente ou em outra caixa do mesmo remédio (estoque_irmaos vem da
// query já somando tudo). Espelha a aba Compras no app.
// Seção à parte (29/09/2026, pedido do gestor): os zerados que TÊM
// substituto na farmácia, com o substituto — pro balcão saber o que
// oferecer. Não entram na lista de reposição.
const todas = $input.all().map((i) => i.json);
const temSubstituto = (p) => Number(p.estoque_irmaos) > 0;
const linhas = todas.filter((p) => !temSubstituto(p));
const cobertos = todas.filter(temSubstituto);
if (linhas.length === 0 && cobertos.length === 0) {
  return [];
}
const hojeLabel = new Date().toLocaleDateString('pt-BR', { timeZone: 'America/Sao_Paulo' });

const blocos = linhas.map((p, i) => {
  const q = Math.round(Number(p.quantidade_vendida_30d));
  return `${i + 1}. ${p.nome_produto} (cód. ${p.codigo_produto}) — ${q} ${q === 1 ? 'vendido' : 'vendidos'} em 30d`;
});

// irmaos_nomes vem "A [outra marca]; B; C [outra caixa]", do maior estoque
// pro menor — mostra o principal e quantos outros há.
const blocosCobertos = cobertos.map((p) => {
  const nomes = String(p.irmaos_nomes || '').split('; ').filter(Boolean);
  const outros = nomes.length > 1 ? ` +${nomes.length - 1}` : '';
  const un = Math.round(Number(p.estoque_irmaos));
  return `• ${p.nome_produto} → ${nomes[0] || 'outro cadastro'}${outros} (${un} un.)`;
});

let mensagem = `📦 *Estoque zerado — produtos de giro alto*\n📅 ${hojeLabel}`;
if (linhas.length > 0) {
  mensagem += `\n\n${blocos.join('\n')}\n\nRepor com prioridade — são os produtos que mais vendem e não têm nenhuma unidade na farmácia (nem em outro cadastro ou marca equivalente).`;
}
if (cobertos.length > 0) {
  mensagem += `\n\n✅ *Zerados com substituto na farmácia (oferecer no balcão):*\n${blocosCobertos.join('\n')}`;
}

return [{ json: { mensagem } }];
